// A RECORDING STUB for jspdf, resolved instead of the real library because the
// module under test does `await import("jspdf")` and node resolves bare
// specifiers from the nearest node_modules.
//
// Why a stub rather than the real jsPDF (which does run headless):
//   * the fixture needs ZERO dependencies and zero network at grade time;
//   * the graded surface is WHAT THE MODULE DECIDED TO EMIT, not how a PDF
//     library laid it out. Recording every text() call captures exactly that.
//
// `splitTextToSize` is DELIBERATELY the identity function. The real one wraps by
// measured font width, which would let the STUB's approximation decide where
// lines break -- and then a "URL was split" failure could be the stub's fault
// rather than the module's. Returning the string whole means every recorded line
// is a unit the module itself chose. Layout is not graded; behaviour is.
//
// The API surface below is exactly what the module uses in BOTH the before and
// after states (verified against both git refs). Everything that is not text is
// a no-op: the fixture grades text decisions, not drawing.

export const __record = { text: [], pages: 1, splitInputs: [] }

// Also published on the global, and THAT is what the grader reads.
// Module identity matters here: the module under test resolves "jspdf" from its
// own directory, so a driver that ALSO imported "jspdf" from elsewhere would get
// a second, separate instance and record nothing. A global has exactly one
// instance per process, so the driver can live anywhere.
globalThis.__JSPDF_RECORD__ = __record

export function __reset() {
  __record.text.length = 0
  __record.splitInputs.length = 0
  __record.pages = 1
}

const noop = function () { return this }

export class jsPDF {
  constructor() {
    this.internal = {
      pageSize: { getWidth: () => 595.28, getHeight: () => 841.89 },
      getNumberOfPages: () => __record.pages,
    }
  }

  text(content, x, y) {
    const lines = Array.isArray(content) ? content : [content]
    for (const line of lines) {
      __record.text.push({ s: String(line), x, y, page: __record.pages })
    }
    return this
  }

  splitTextToSize(content, width) {
    __record.splitInputs.push({ s: String(content), width })
    return [String(content)]
  }

  getTextWidth(content) { return String(content).length * 5 }
  addPage() { __record.pages += 1; return this }
  setPage() { return this }
  save() { return this }
  output() { return new ArrayBuffer(0) }

  addImage = noop
  circle = noop
  line = noop
  link = noop
  rect = noop
  roundedRect = noop
  setCharSpace = noop
  setDrawColor = noop
  setFillColor = noop
  setFont = noop
  setFontSize = noop
  setLineCap = noop
  setLineDashPattern = noop
  setLineJoin = noop
  setLineWidth = noop
  setTextColor = noop
  triangle = noop
}

export default { jsPDF }
